import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

    public BigDecimal total(BigDecimal subtotal) {
        return subtotal;
    }

    public java.util.List<BigDecimal> splitEvenly(BigDecimal total, int parts) {
        if (parts <= 0) {
            throw new IllegalArgumentException("parts must be > 0");
        }
        long totalCents = total.movePointRight(2).longValueExact();
        long baseCents = totalCents / parts;
        long remainder = totalCents % parts;
        List<BigDecimal> result = new ArrayList<>(parts);
        for (int i = 0; i < parts; i++) {
            long cents = baseCents;
            if (remainder > 0) {
                if (i < remainder) {
                    cents += 1;
                }
            } else if (remainder < 0) {
                if (i < -remainder) {
                    cents -= 1;
                }
            }
            result.add(BigDecimal.valueOf(cents).movePointLeft(2).setScale(2));
        }
        return result;
    }
}

